mapper.select:
SELECT qpr.id, qpr.question_id AS questionId, q.title AS questionTitle, q.difficulty AS questionDifficulty, qpr.is_correct AS isCorrect, qpr.duration_seconds AS durationSeconds, qpr.practice_date AS practiceDate, qpr.create_time AS createTime FROM question_practice_record qpr LEFT JOIN question q ON q.id = qpr.question_id
qpr.user_id = #{userId}
AND qpr.id < #{cursor}
ORDER BY qpr.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM question_practice_record
WHERE user_id = #{userId}
  AND practice_date = #{practiceDate}
  AND is_correct = 1
